# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM ÖNCESİNDE MEKKE VE KÂBE\'NİN KONUMU</text>\n  <rect x="35" y="60" width="190" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kâbe\'nin Kutsiyeti</text>\n  <text x="130" y="115" text-anchor="middle" font-size="11" fill="#334155">Hz. İbrahim ve oğlu</text>\n  <text x="130" y="135" text-anchor="middle" font-size="11" fill="#334155">Hz. İsmail tarafından</text>\n  <text x="130" y="155" text-anchor="middle" font-size="11" fill="#334155">inşa edilmiştir.</text>\n  <text x="130" y="180" text-anchor="middle" font-size="11" fill="#334155">Tevhidin merkezidir.</text>\n  <text x="130" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Beytullah (Allah\'ın Evi)</text>\n  <rect x="255" y="60" width="190" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Mekke\'nin Önemi</text>\n  <text x="350" y="115" text-anchor="middle" font-size="11" fill="#334155">Ticaret kervanlarının</text>\n  <text x="350" y="135" text-anchor="middle" font-size="11" fill="#334155">kavşak noktasıdır.</text>\n  <text x="350" y="155" text-anchor="middle" font-size="11" fill="#334155">Yemen-Suriye yolu</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11" fill="#334155">üzerinde güvenli şehir.</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">Dini ve ticari merkez</text>\n  <rect x="475" y="60" width="190" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="570" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kureyş ve Görevler</text>\n  <text x="570" y="115" text-anchor="middle" font-size="11" fill="#334155">Sikâye (Hacılara su verme)</text>\n  <text x="570" y="140" text-anchor="middle" font-size="11" fill="#334155">Rifâde (Ağırlama/yemek)</text>\n  <text x="570" y="165" text-anchor="middle" font-size="11" fill="#334155">Abdülmuttalib şehrin</text>\n  <text x="570" y="185" text-anchor="middle" font-size="11" fill="#334155">saygın lideriydi.</text>\n  <text x="570" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Hacılara Hizmet</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİL VAKASI VE FİL SURESİ\'NİN MESAJI</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="187" y="82" text-anchor="middle" font-size="14" font-weight="bold" fill="#b91c1c">Ebrehe\'nin Kâbe\'yi Yıkma Girişimi</text>\n  <text x="50" y="110" font-size="11.5" fill="#334155">• Yemen Valisi Ebrehe, San\'a\'da Kuleys adında</text>\n  <text x="65" y="128" font-size="11" fill="#475569">büyük bir kilise yaptırdı.</text>\n  <text x="50" y="150" font-size="11.5" fill="#334155">• Arapların Kâbe\'ye gitmesini önleyemeyince</text>\n  <text x="65" y="168" font-size="11" fill="#475569">fillerin bulunduğu büyük bir ordu kurdu.</text>\n  <text x="50" y="190" font-size="11.5" fill="#334155">• Abdülmuttalib: "Ben develerin sahibiyim,</text>\n  <text x="65" y="208" font-size="11" font-weight="bold" fill="#b91c1c">Kâbe\'nin ise onu koruyacak Sahibi vardır."</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="82" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">Ebâbîl Kuşları ve İlahi Koruma</text>\n  <text x="375" y="110" font-size="11.5" fill="#334155">• Kâbe\'ye yönelen ordu Mahmud adlı filin</text>\n  <text x="390" y="128" font-size="11" fill="#475569">yere çökmesiyle durdu.</text>\n  <text x="375" y="150" font-size="11.5" fill="#334155">• Yüce Allah sürü sürü Ebâbîl kuşlarını</text>\n  <text x="390" y="168" font-size="11" fill="#475569">pişmiş balçık taşlarıyla gönderdi.</text>\n  <text x="375" y="190" font-size="11.5" fill="#334155">• Ordu \'yenilmiş ekin yaprağına\' döndü.</text>\n  <text x="512" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Fil Suresi bu hadiseyi ebedileştirmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN DÜNYAYA GELİŞİ (571)</text>\n  <rect x="40" y="60" width="190" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="135" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Doğum Tarihi ve Yeri</text>\n  <text x="135" y="120" text-anchor="middle" font-size="12" fill="#334155">20 Nisan 571</text>\n  <text x="135" y="145" text-anchor="middle" font-size="12" fill="#334155">12 Rebiülevvel Pazartesi</text>\n  <text x="135" y="170" text-anchor="middle" font-size="12" fill="#334155">Mekke\'de doğdu.</text>\n  <text x="135" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Mevlid Kandili</text>\n  <rect x="255" y="60" width="190" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Ailesi ve Soyu</text>\n  <text x="350" y="120" text-anchor="middle" font-size="12" fill="#334155">Babası: Abdullah</text>\n  <text x="350" y="145" text-anchor="middle" font-size="12" fill="#334155">Annesi: Âmine</text>\n  <text x="350" y="170" text-anchor="middle" font-size="12" fill="#334155">Dedesi: Abdülmuttalib</text>\n  <text x="350" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">Kureyş / Hâşimoğulları</text>\n  <rect x="470" y="60" width="190" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="565" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Muhammed İsmi</text>\n  <text x="565" y="120" text-anchor="middle" font-size="12" fill="#334155">Dedesi tarafından</text>\n  <text x="565" y="145" text-anchor="middle" font-size="12" fill="#334155">\'Muhammed\' adı verildi.</text>\n  <text x="565" y="170" text-anchor="middle" font-size="11" fill="#334155">Anlamı: \'Çokça övülen\'</text>\n  <text x="565" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Göklerde ve yerde övülsün</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
